use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let s = input.as_str().unwrap();
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return Value::Bool(false);
    }
    for part in parts {
        if !part.chars().all(|c| c.is_digit(10)) {
            return Value::Bool(false);
        }
        if part == "0" && part.len() > 1 {
            return Value::Bool(false);
        }
    }
    Value::Bool(true)
}
